const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });

  const htmlPath = path.resolve(__dirname, 'bump-chart.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });

  // Give Chart.js a moment to render
  await page.waitForTimeout(1500);

  const clip = await page.evaluate(() => {
    const el = document.querySelector('.chart-wrap') || document.body;
    const r = el.getBoundingClientRect();
    return { x: r.left, y: r.top, width: r.width, height: r.height };
  });

  await page.screenshot({
    path: '/app/output/result.png',
    clip,
    type: 'png',
  });

  await browser.close();
  console.log('Done: /app/output/result.png');
})();

